pub fn texcubeAttrSlot(attr_name: []const u8) ?usize {
    if (std.mem.eql(u8, attr_name, "pos")) {
        return 0;
    }
    if (std.mem.eql(u8, attr_name, "texcoord0")) {
        return 1;
    }
    if (std.mem.eql(u8, attr_name, "normal0")) {
        return 2;
    }
    if (std.mem.eql(u8, attr_name, "modifierColor0")) {
        return 3;
    }
    return null;
}
pub fn texcubeTextureSlot(tex_name: []const u8) ?usize {
    if (std.mem.eql(u8, tex_name, "tex")) {
        return 0;
    }
    return null;
}
pub fn texcubeSamplerSlot(smp_name: []const u8) ?usize {
    if (std.mem.eql(u8, smp_name, "smp")) {
        return 0;
    }
    return null;
}
pub fn texcubeUniformBlockSlot(ub_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        return 0;
    }
    return null;
}
pub fn texcubeUniformBlockSize(ub_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        return @sizeOf(VsParams);
    }
    return null;
}
pub fn texcubeUniformOffset(ub_name: []const u8, u_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        if (std.mem.eql(u8, u_name, "mvp")) {
            return 0;
        }
    }
    return null;
}
pub fn texcubeUniformDesc(ub_name: []const u8, u_name: []const u8) ?sg.GlslShaderUniform {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        if (std.mem.eql(u8, u_name, "mvp")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .MAT4;
            desc.array_count = 0;
            desc.glsl_name = "mvp";
            return desc;
        }
    }
    return null;
}
pub fn texcubeStorageBufferSlot(sbuf_name: []const u8) ?usize {
    _ = sbuf_name;
    return null;
}
pub fn texcubeStorageImageSlot(simg_name: []const u8) ?usize {
    _ = simg_name;
    return null;
